private static List<FieldFormatter> fieldFormatters;
private static PeriodFieldAffix prefix;
private static PeriodFieldAffix suffix;

@Rule
public ExpectedException expectedEx = ExpectedException.none();

@BeforeClass
public static void setup(){
    fieldFormatters = new ArrayList<>();
    fieldFormatters.add(new FieldFormatter(1, 0, 3, false, DurationFieldType.SECONDS, null, null, null));
    fieldFormatters.add(new FieldFormatter(2, 1, 3, true, DurationFieldType.MINUTES, fieldFormatters.get(0), prefix, suffix));
    fieldFormatters.add(new FieldFormatter(3, 2, 3, false, DurationFieldType.HOURS, fieldFormatters.get(1), prefix, suffix));
    fieldFormatters.add(new FieldFormatter(4, 3, 3, true, DurationFieldType.DAYS, fieldFormatters.get(2), prefix, suffix));
    prefix = mock(PeriodFieldAffix.class);
    suffix = mock(PeriodFieldAffix.class);
}

@Test
public void testPrintTo_whenMinPrintedDigitsIs1_shouldAppendUnpaddedInteger(){
    StringBuffer buf = new StringBuffer();
    ReadablePeriod period = mock(ReadablePeriod.class);
    when(period.getSeconds()).thenReturn(42);
    fieldFormatters.get(0).printTo(buf, period, Locale.ENGLISH);
    Assert.assertEquals("42", buf.toString());
}

@Test
public void testPrintTo_whenMinPrintedDigitsIsGreaterThan1_shouldAppendPaddedInteger(){
    StringBuffer buf = new StringBuffer();
    ReadablePeriod period = mock(ReadablePeriod.class);
    when(period.getSeconds()).thenReturn(42);
    fieldFormatters.get(0).printTo(buf, period, Locale.ENGLISH);
    fieldFormatters.get(1).printTo(buf, 42, Locale.ENGLISH);
    Assert.assertEquals(" 42", buf.toString());
}

@Test
public void testPrintTo_whenFieldTypeIsSecondsMillis_shouldAppendDecimalPart(){
    StringBuffer buf = new StringBuffer();
    ReadablePeriod period = mock(ReadablePeriod.class);
    when(period.getMilliseconds()).thenReturn(42);
    fieldFormatters.get(0).printTo(buf, period, Locale.ENGLISH);
    Assert.assertEquals("42.0", buf.toString());
}

@Test
public void testPrintTo_whenFieldTypeIsGreaterThanSecondsMillis_shouldNotAppendDecimalPart(){
    StringBuffer buf = new StringBuffer();
    ReadablePeriod period = mock(ReadablePeriod.class);
